questiontext.text:
\(\require{mhchem}\)
<p>Balance the following reaction. The substances are given, but all stoichiometric coefficients are omitted.</p>
<p style="font-size: 1.3em; text-align: center;">\({@reaction_display@}\)</p>
<p>Enter the complete balanced equation. Use <code>+</code> between substances. Coefficients may be integers, decimals, or fractions, for example <code>2H2</code>, <code>1.5O2</code>, or <code>3/2O2</code>.</p>
<div style="display:flex; justify-content:center; align-items:center; width:100%;">
<table><tr><td><input id="[[quid id='_fake1'/]]" style="width:100%;"/></td><td><b style="font-size:x-large;">→</b></td><td><input id="[[quid id='_fake2'/]]" style="width:100%;"/></td></tr></table>
</div>
<div style="text-align:center;">[[validation:ans1]]</div>
<div style="text-align:center;">[[feedback:prt1]]</div>
<p hidden>[[input:ans1]]</p>
[[javascript]]
import * as peggy from 'https://cdn.jsdelivr.net/npm/peggy@5.1.0/browser/peggy.min.js';
import * as stack_mp from 'https://stack-demo.maths.ed.ac.uk/demo/question/type/stack/corsscripts/cors.php?name=stackmplite.min.js';

stack_mp.MPString.prototype.toString = function() {
 return '"' + this.value.replaceAll("\\", "\\\\").replaceAll('"', '\\"') + '"';
};

Promise.all([
 stack_js.request_access_to_input('ans1', true),
 stack_js.request_access_to_input('fake1', true),
 stack_js.request_access_to_input('fake2', true)
]).then(([ans1ref, fake1ref, fake2ref]) => {
 const chem_parser = window.peggy.generate(`
Expression = _ ex:Addition _ { return ex; } / _ ex:Term _ { return ex; }
Addition = a:Term b:AdditionTail { return [a, ...b].join(' + '); }
AdditionTail = _ '+' _ a:Term b:AdditionTail { return [a, ...b]; } / _ '+' _ a:Term { return [a]; }
Term = Multiplied / Component
Multiplied = a:Coefficient _ [*]? _ b:Component { return a + ' * ' + b; }
Component = Ion / Molecule / Group / Atom
Atom = [A-Z][a-z]* { return 'sc_atom("' + text() + '")'; }
Ion = a:Atom c:Charge { return 'sc_charge(' + a + ',' + c + ')'; } / a:Molecule c:Charge { return 'sc_charge(' + a + ',' + c + ')'; } / a:Group c:Charge { return 'sc_charge(' + a + ',' + c + ')'; }
Charge = '^' '{' b:Integer '-' '}' { return '-' + b; } / '^' '{' b:Integer '+' '}' { return b; } / '^' '{' '-' '}' { return '-1'; } / '^' '{' '+' '}' { return '1'; } / '^' b:Integer '-' { return '-' + b; } / '^' b:Integer '+' { return b; } / '^-' { return '-1'; } / '^+' { return '1'; }
Group = '(' _ a:Component _ ')' { return 'sc_group(' + a + ')'; } / '[' _ a:Component _ ']' { return 'sc_groupb(' + a + ')'; }
Multiple = a:Atom b:Subscript { return 'sc_mult(' + a + ',' + b + ')'; } / a:Group b:Subscript { return 'sc_mult(' + a + ',' + b + ')'; }
Subscript = '_' '{' b:Integer '}' { return b; } / [_]? b:Integer { return b; }
Molecule = a:MoleculeComponent b:MoleculeTail { return 'sc_molecule([' + a + ',' + b.join(',') + '])'; } / Multiple
MoleculeComponent = Multiple / Group / Atom
MoleculeTail = a:MoleculeComponent b:MoleculeTail { return [a, ...b]; } / a:MoleculeComponent { return [a]; }
Coefficient = Fraction / Decimal / Integer
Fraction = a:Integer _ '/' _ b:Integer { return a + '/' + b; }
Decimal = [0-9]+ '.' [0-9]+ { return text(); }
Integer = [0-9]+ { return text(); }
_ = [ \t\n\r]*
 `);
 const leftside = document.getElementById(fake1ref);
 const rightside = document.getElementById(fake2ref);
 const real = document.getElementById(ans1ref);
 const update = () => {
  const raw = '[' + (new stack_mp.MPString(leftside.value.trim())).toString() + ',' + (new stack_mp.MPString(rightside.value.trim())).toString() + ']';
  if (raw === '["",""]') { real.value = ''; real.dispatchEvent(new Event('change')); return; }
  try {
   if (leftside.value.trim() === '' || rightside.value.trim() === '') throw new Error('Fill in both sides of the equation.');
   real.value = 'sc_reaction(' + chem_parser.parse(leftside.value.trim()) + ',' + chem_parser.parse(rightside.value.trim()) + ')';
  } catch (error) { real.value = 'sc_err(' + raw + ',' + (new stack_mp.MPString(error.message)).toString() + ')'; }
  real.dispatchEvent(new Event('change'));
 };
 leftside.addEventListener('change', update);
 rightside.addEventListener('change', update);
});
[[/javascript]]

questionvariables.text:
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Tests/reactions.mac");
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Tests/reaction_parser.mac");

reaction_names: ["SodiumWater", "MagnesiumCO2", "AluminumHCl", "WaterGasShift", "SynthesisAmmonia", "SynthesisWater", "KClO3Decomposition", "IronOxideReduction", "CuOReduction", "N2O4Dissociation"];
rxn_name: rand(reaction_names);
reaction_display: chem_reaction_equation_without_coefficients(rxn_name);
ta1: reaction_to_sc(rxn_name);
